# 批注数据：src/utils/processUserInput/processSlashCommand.tsx
# slug = src_utils_processUserInput_processSlashCommand_tsx
ANNOTATIONS = [
    (49, 'before', '''SlashCommandResult：在普通处理结果上额外带上本次命中的 Command 对象，供上层区分「斜杠命令」这一类特殊结果。'''),
    (53, 'before', '''MCP 安定轮询参数：后台 fork 子 agent 前先等 MCP 服务器连上。MCP 通常启动后 1-3 秒连上，这里给 10 秒余量覆盖慢的 SSE 握手；轮询间隔 200 毫秒。'''),
    (62, 'before', '''executeForkedSlashCommand：以 fork 子 agent 的方式执行斜杠命令——把技能内容、agent 定义、提示词准备好后，按 context:fork 的规则在后台或前台跑子 agent。'''),
    (102, 'after', '''后台模式（fire-and-forget）：当 KAIROS 且 kairosEnabled 开启时，子 agent 在后台跑，立刻返回空消息、不阻塞用户输入；完成后把结果作为隐藏的 isMeta 提示重新入队，由主 agent 下一轮决定如何处理。没有这套机制的话，启动时 N 个定时任务会串行（子 agent + 主 agent 轮次）卡住输入。'''),
    (118, 'after', '''工作量标签：handlePromptSubmit 把整轮包在 runWithWorkload（AsyncLocalStorage）里，ALS 上下文在 void 触发时捕获并贯穿所有 await；但重新入队的第二条提示跑在全新的 runWithWorkload 边界里，需要自己的 QueuedCommand.workload 标签才能保留归属。'''),
    (134, 'after', '''后台执行体：先轮询等 MCP 客户端都不再是 pending 再刷新工具列表；然后跑子 agent，收集消息、抽出结果文本，最后把结果包成 scheduled-task-result 重新入队。失败也入队一条 status=failed 的结果，保证队列不被卡死。'''),
    (304, 'before', '''looksLikeCommand：判断一段字符串是否「像」合法命令名——只含字母、数字、冒号、连字符、下划线。含其它字符的更可能是文件路径或普通输入，不该当命令解析。'''),
    (309, 'before', '''processSlashCommand：斜杠命令的总入口。先解析输入，解析失败就报「命令形如 /command [args]」；再按命令类型分流到 getMessagesForSlashCommand，并对未知命令、本地命令、有效命令分别构造返回结果与遥测事件。'''),
    (333, 'after', '''命令不存在时的分流：先判断它「像不像命令名」以及「是不是真实存在的文件路径」。像命令名且不是文件路径 → 记 invalid 遥测并返回 Unknown skill；否则当作普通用户输入，记 user_prompt 事件并继续向模型查询。'''),
    (357, 'after', '''gh-32591：未知命令时保留 args，让用户无需重打就能复制再提交；系统警告仅 UI 可见（发往 API 前会被过滤）。'''),
    (398, 'after', '''本地斜杠命令（newMessages 为空）走这条：按是否插件命令补上插件遥测元数据，再返回不查询的结果（或带 nextInput 让前端自动提交下一步输入）。'''),
    (453, 'after', '''无效命令的特例：当返回两条消息且第二条是「Unknown command:」开头的用户消息时，若输入不像常见文件路径（/var、/tmp、/private）才记 invalid 遥测，否则静默放行，避免把文件路径误判成无效命令。'''),
    (512, 'after', '''压缩结果特例：若新消息首条是压缩边界消息，它自己会处理合成警告消息的排序，这里据此决定最终是否要在前面补一条合成警告。'''),
    (525, 'before', '''getMessagesForSlashCommand：按命令类型（local-jsx / local / prompt）分别构造消息。先记录技能使用用于排序，再拦截 userInvocable 为 false 的「仅模型可调」技能，最后进入类型分发。'''),
    (535, 'after', '''仅模型可调用：userInvocable 为 false 的技能只能由模型通过 SkillTool 触发；用户直接打会被拦截，并提示「让 Claude 帮你用这个技能」。'''),
    (550, 'before', '''类型分发：local-jsx 用 onDone 回调驱动 UI 模态；local 直接加载并调用命令函数；prompt 则按 context:fork 决定走后台 fork 还是前台取提示词。'''),
    (591, 'after', '''全屏模式下的转写取舍：全屏里命令只显示一个居中模态面板，转场通知已够反馈，所以以 dismissed 结尾的「XXX dismissed」提示可以跳过不进转录；全屏外则保留，让滚动历史显示跑过什么。'''),
    (628, 'after', '''防护：若 onDone 在 mod.call() 期间就已触发（早退路径先调 onDone 再返回 JSX），这里跳过 setToolJSX，否则在外层 Promise 已 resolve、executeUserInput 可能已清掉本地 JSX 之后再设 isLocalJSXCommand，会导致它卡在 true 从而阻塞队列处理器与输入框聚焦。'''),
    (679, 'after', '''compact 类型结果：把斜杠命令消息追加到 messagesToKeep，让附件与 hook 结果排在用户消息之后；同时重置 microcompact 状态（整段压缩替换了全部消息，旧工具 ID 失效，但预算状态无需重置——过期条目是惰性的，UUID 不复用）。'''),
    (723, 'before', '''prompt 类型：若命令声明 context:fork 就走后台 fork 子 agent；否则取 prompt 型斜杠命令的消息。AbortError 单独处理成「Interrupted」提示，其它错误回显到 local-command-stderr。'''),
    (762, 'after', '''分发外层兜底：MalformedCommandError 转成一条用户消息返回；其它异常继续向上抛，交由更上层处理。'''),
    (778, 'before', '''formatCommandInput：把命令名与参数拼成展示用的输入字符串（走统一的 tag 格式化）。'''),
    (786, 'before', '''formatSkillLoadingMetadata：构造技能加载消息的元数据，渲染成 Skill(name) 形式；只含技能名，不含参数。'''),
    (794, 'before', '''formatSlashCommandLoadingMetadata：构造斜杠命令加载元数据，渲染成 /name 形式；若有参数再附 command-args 段。'''),
    (803, 'before', '''formatCommandLoadingMetadata：统一入口——用户可调用技能显示成 /command（与普通斜杠命令一致），仅模型技能（来自 skills/plugin/mcp）显示成「The X skill is running」。优先用 command.name（含插件前缀的限定名）而非可能剥掉前缀的 userFacingName。'''),
    (817, 'before', '''processPromptSlashCommand：供 Skill 工具等直接按命令名取 prompt 型斜杠命令的消息；命令不存在或类型不对就抛错。'''),
    (827, 'before', '''getMessagesForPromptSlashCommand：真正构造 prompt 型命令消息的地方。处理协调器模式短路、注册技能钩子、记录技能调用用于压缩保留，并组装主消息（含粘贴的图片、前置输入块、附件、命令权限）。'''),
    (837, 'after', '''协调器模式短路：在主线程且开启 COORDINATOR_MODE、又不是子 agent 时，不加载完整技能内容与权限（协调器只有 Agent 与 TaskStop 工具，那些没用），只发一段简要说明，告诉协调器如何把这个技能委派给 worker。worker 是进程内运行并继承协调器环境变量，会在调用 Skill 工具时拿到真实内容。'''),
    (874, 'after', '''注册技能钩子：在 hooks 仅锁定（技能未锁）模式下，用户技能仍会加载到此处——就在 source 已知的地方拦下钩子注册，与 runAgent.ts 里 agent 前 matter 的门控保持一致。'''),
    (896, 'after', '''附件抽取与发现：从命令参数里抽取 @提及、MCP 资源、SKILL.md 里的 agent 提及作为附件；skipSkillDiscovery 防止 SKILL.md 内容本身触发技能发现——它是元内容而非用户意图，一个很大的 SKILL.md（如 110KB）会触发分块 AKI 查询，给每次技能调用凭空加几秒延迟。'''),
]
